import { ref, reactive } from 'vue';

// Create and export a default Vue component named 'StateComparison' with a setup function that returns an empty object
export default {
  setup() {
    // Create counter state variable here
    const counter = ref(0);

    // Create increment handler here
    function increment() {
      counter.value++;
    }

    // Create useReducer-style state object here
    const reducerState = reactive({ count: 0 });

    // Define reducer function here
    function reducer(state, action) {
      switch (action.type) {
        case 'INCREMENT':
          return { count: state.count + 1 };
        case 'DECREMENT':
          return { count: state.count - 1 };
        default:
          return state;
      }
    }

    // Create dispatch function here
    function dispatch(action) {
      const newState = reducer(reducerState, action);
      Object.assign(reducerState, newState);
    }

    return {
      // Add template structure here
      counter,
      increment,
      reducerState,
      dispatch
    };
  }
};
